#include <stdio.h>

/* 挑最短：一轮挑一只最短的换到最前面 */
void pick_min(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[min_idx]) {
                min_idx = j;
            }
        }
        int t = a[i];
        a[i] = a[min_idx];
        a[min_idx] = t;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    pick_min(a, n);

    printf("挑最短：");
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    return 0;
}

items.explanation:
这一招的骨架是一条**两层的活儿**：外面挑「轮到哪一段了」，里面挑「这一段里最短的是谁」喵。

```text
for (int i = 0; i < n - 1; i++) {
    int min_idx = i;
    for (int j = i + 1; j < n; j++) {
        if (a[j] < a[min_idx]) {
            min_idx = j;
        }
    }
    int t = a[i];
    a[i] = a[min_idx];
    a[min_idx] = t;
}
```

三处值得多念两遍：

**① `min_idx` 记的是位子，不是数。** 记数的话，换的时候你就不知道该跟谁换了 —— 记住「第几只」，才有得换。

**② `min_idx = i;` 里的那个 `i` 不能写成 `0`。** 每一轮挑的是**还没排好的那一段**（从第 `i` 只开始），写成 `0` 就变成每一轮都在整排里找最小 —— 已经排好的前几只又被卷进来，越排越乱。

**③ 换的是 `a[i]` 和 `a[min_idx]`。** 把「这一段的开头」和「最短的那只」调个个儿；下一轮开头往后挪一格，再挑一次。外层走到 `n - 1` 就够了 —— 最后一只不用挑，它一定是剩下的里最大的那只喵。

本喵给你留一句分头记：**一轮一只，挑最短的换到前面。**
